# Generated by build.py from recipe.yml for recipe sftp-refuse-the-first-login. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--throwaway-hostkey', '-u', 'alice:s3cret', '--allow-uploads', '--directory', 'deploy', '--fault', '"refuse-login;times=2"', 'sftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -k -u alice:s3cret --retry 1 --retry-all-errors --retry-delay 1 -w "%{num_retries}\n" -T release.txt sftp://127.0.0.1:8080/release.txt } finally { Stop-Process $server0 }
